  "overview": "体验由独一无二的泰勒·斯威夫特带来的、令人叹为观止的“时代巡回演唱会”。 《泰勒·斯威夫特：时代巡回演唱会》（Taylor Swift: The Eras Tour）是一部于2023年上映的演唱会音乐纪录电影，由美国创作歌手泰勒·斯威夫特亲自担任制片并主演，萨姆·伦奇执导。影片全程拍摄于巡演2023年8月3日至5日在美国洛杉矶SoFi体育场举办的三场演唱会，是“泰勒·斯威夫特 'Eras' 世界巡回演唱会”的电影版本。 该片于2023年10月13日在北美正式上映，12月13日",
