  "overview": "东南亚某地，失语的维修工王伟与女儿雨晴相依为命。一天，雨晴在街头被一个人口贩卖组织掳走，王伟向警方求助，却发现当地执法系统充斥着腐败与冷漠。走投无路之下，他只能凭自己的力量追查女儿下落，并在过程中结识记者纳文。纳文的妻子曾因调查同一犯罪网络而神秘失踪，两人因此决定联手，沿着有限的线索一步步深入地下犯罪世界。面对盘根错节的黑恶势力和接连出现的危险，王伟为了救回女儿，不得不重新展现自己隐藏已久的战斗能力……",
