  "overview": "出身泰国华人家庭的阿安大学辍学后一直没有稳定工作，平日做着游戏直播。一次，他看到堂妹阿梅因悉心照顾病重的爷爷而继承房产，便动起了效仿她的念头。恰逢姥姥被确诊为晚期癌症，阿安索性搬去陪伴照料，希望借此成为最受宠爱的外孙，最终获得姥姥留下的遗产。然而，精明的姥姥并没有那么容易被讨好，两个舅舅也各自有着自己的盘算。原本把照顾姥姥当成一条“致富捷径”的阿安，在陪她买菜、卖粥、看病和共同生活的日子里，逐渐开始真正走进这个老人以及整个家庭的生活……",
