  "overview": "随着战争阴云笼罩世界，各国之间的军事竞赛愈演愈烈。为了抢占先机，美国军方找到量子力学与核物理学家罗伯特·奥本海默，任命他领导洛斯阿拉莫斯实验室，并参与推进绝密的曼哈顿计划。在科学家们争分夺秒的研发下，人类历史上第一颗原子弹最终在荒漠中成功引爆。然而，当这种足以改变世界的力量真正诞生后，奥本海默也开始重新审视自己的选择以及核武器可能带来的后果。随着战争结束，他的政治立场和过往经历又让他逐渐卷入一场更加复杂的政治风暴……",
