  "overview": "哈利即将开始在霍格沃茨的第三学年，一则危险消息却让整个魔法世界陷入紧张：臭名昭著的囚犯小天狼星·布莱克从阿兹卡班越狱，而所有人都认为他的目标正是哈利。为了追捕逃犯，令人恐惧的摄魂怪被派驻霍格沃茨周围，哈利却发现自己对它们有着异乎寻常的强烈反应。在新任黑魔法防御术教授卢平的帮助下，他开始学习抵御摄魂怪的方法。随着调查深入，哈利逐渐发现小天狼星不仅与伏地魔有关，还与自己的父母有着密切的过去，而关于父母遇害的往事似乎远比他一直相信的更加复杂……",
