  "imdb_id": "tt0330373",
  "overview": "哈利迎来了在霍格沃茨的第四个学年，这一年学校将举办久负盛名而又危险重重的“三强争霸赛”，来自布斯巴顿和德姆斯特朗两所魔法学校的学生也来到霍格沃茨参加竞争。按照规定，只有年满17岁的学生才有资格报名，然而负责选出勇士的“火焰杯”却意外吐出了年仅14岁的哈利·波特的名字，使他成为比赛中史无前例的第四名勇士。哈利坚称自己从未报名，却不得不面对火龙、黑湖和魔法迷宫等一系列危险考验。与此同时，魁地奇世界杯上出现的食死徒与黑魔标记，以及哈利不断出现的噩梦，都预示着这场比赛背后还隐藏着更加",
