  "overview": "在所有哺乳动物共同生活的现代都市“疯狂动物城”，兔子朱迪从小就梦想成为一名警察。凭借自己的努力，她终于从警校毕业，成为疯狂动物城警察局第一只兔子警官。然而初来乍到的朱迪并没有得到重用，而是被安排负责街头停车执法。与此同时，城中接连发生动物失踪事件，一心想证明自己的朱迪主动接下寻找失踪水獭的案件，并必须在48小时内查出线索，否则便要离开警局。调查过程中，她不得不与精明狡猾的狐狸尼克合作。原本互不信任的一兔一狐由此成为临时搭档，而这起看似普通的失踪案，也逐渐牵出隐藏在疯狂动物城背",
