  "imdb_rating": null,
  "imdb_id": "tt0371746",
  "overview": "斯塔克工业是美国军方的重要武器供应商，掌门人托尼·斯塔克天资聪颖，却也过着放纵不羁的富豪生活，在助手维吉尼亚·波茨和公司元老俄巴迪亚·斯坦的协助下经营着庞大的军火事业。一次前往中东展示新型武器时，托尼遭到武装分子袭击并被俘，体内残留的弹片随时可能危及心脏。在英森博士的帮助下，他利用微型电弧反应炉维持胸前的电磁装置，并暗中制造出一套钢铁盔甲逃离囚禁。回到美国后，托尼重新审视自己的事业，并不断改进这套战甲，却也逐渐发现斯塔克工业背后隐藏着更危险的秘密……",
