  "overview": "就读于美术学校的大学生光浩，总是粗暴又没耐心地对待女友。过著百无聊赖生活的他，某日获得爷爷的允许后便迳行前往首尔。正当无处可去的光浩来到一家商店打算问路时，一位穿著性感的女性吸引了他的目光，没想到她竟然就是光浩幼时朝思暮想的表妹智允，光浩就这麽寄宿在表妹智允家。随著时间相处，光浩和智允的儿时记忆纷纷浮上心头，两人的感情在不知不觉间急速升温，究竟他们能否守护这睽违10年的忐忑爱情？",
