  "overview": "历经此前的种种考验，阿伦黛尔王国终于恢复了往日的平静。艾莎女王、安娜公主以及雪宝、克斯托夫和驯鹿斯文过着安宁的生活。然而最近，艾莎总会听到一个神秘声音的呼唤。为了寻找声音的来源，也为了揭开自己冰雪魔法背后的秘密，她决定踏上未知的旅程，安娜和伙伴们也紧随其后。他们来到常年被浓雾笼罩的魔法森林，并向更加神秘危险的暗海前进。在那里，不仅隐藏着强大的自然力量，也埋藏着关于阿伦黛尔王国、艾莎魔法来源以及两姐妹家族过去的秘密。一场寻找真相与自我的旅程就此展开……",
