  "overview": "在四面环海、风景如画的阿伦黛尔王国，生活着艾莎和安娜两位公主。艾莎天生拥有操控冰雪的能力，随着年龄增长，她的力量越来越强，童年时甚至险些伤及妹妹。为了保护安娜，艾莎不得不隐藏自己的能力，两姐妹也因此逐渐疏远。父母在一场海难中去世后，艾莎终于到了加冕为女王的年龄，各国宾客齐聚阿伦黛尔。一直小心隐藏秘密的艾莎，却因安娜想要与初次见面的汉斯王子结婚而情绪失控，意外暴露了自己的能力。惊慌之下，她逃入雪山，并用魔法建造了一座冰雪宫殿，而整个阿伦黛尔也因此陷入严寒。为了找回姐姐并拯救王国",
