  "overview": "五年前的巴音布鲁克一战后，张驰虽然完成了那场孤注一掷的比赛，却因赛车铅封始终未能找到，成绩被组委会取消。离开赛场后，他靠经营驾校维持生活，却又遭遇网络争议，曾经的传奇车手逐渐淡出人们视线。就在张驰几乎放下赛车时，一家濒临停产的老头乐车厂主动找到他，希望赞助车队参加最后一届巴音布鲁克拉力赛。张驰重新召集孙宇强、记星等老搭档，并遇到了颇具赛车天赋的年轻人厉小海以及驾校学员刘显德。一支看似并不完美的车队由此重新上路，为再次站上巴音布鲁克展开准备……",
