  "overview": "　　故事发生在位于湘西的穷苦农村中，在这里，男人们留在家中劳作耕地，而女人们则要离开家，前往城镇“做生意”，而她们所做的生意，其实就是出卖自己的身体。阿七是这些女人们中的一员，日子虽然过得十分凄惨却也习以为常。一天，阿七的丈夫在家忙完了农活，觉得百般无聊，于是决定去找阿七。看到自己的老婆辗转在不同的男人身下，阿七的丈夫心里十分不是滋味，但与此同时他亦明白，如果阿七不出来工作，家里就没有饭吃。\r 　　富裕的油商张老板看上了阿七的美貌，想要将她买走做姨太太，这让阿七的丈夫感到无法",
