  "overview": "即将继承阿斯加德王位的雷神索尔勇猛强大，却也傲慢冲动。当冰霜巨人闯入阿斯加德后，他不顾父亲奥丁的命令，擅自带领洛基、希芙等伙伴前往约顿海姆反击，险些重新挑起两个国度之间的战争。震怒的奥丁因此剥夺索尔的神力，将他连同雷神之锤放逐到地球。在新墨西哥州，失去力量的索尔遇到了天体物理学家简·福斯特和她的伙伴，并试图重新取回雷神之锤，却发现自己已经无法将它举起。与此同时，阿斯加德的局势也因洛基发生变化。被迫以普通人的身份生活在地球上的索尔，开始重新认识力量、责任以及真正成为王者所需要的",
