  "overview": "在O（柯瑞妮·克莱瑞 Corinne Clery 饰）的内心里，有关雷尼（乌多·奇尔 Udo Kier 饰）的一切都是神圣和至高无上的，包括被雷尼带到一幢神秘的郊区别墅里接受残忍的SM女郎训练。在那里，O如同一个动物那样失去了全部的尊严，即使是在这样的黑暗阴影里，每当想到雷尼，O依然觉得生命充满了温暖和希望。 O散发出了惊人的魅力，所有遇见她的男人都在冥冥之中被她所吸引，包括雷尼的表哥史蒂文（安东尼·斯特尔 Anthony Steel 饰）。渐渐的，O明白了这个邪恶世界的生存",
